class UniqueHandle {
    int* data;
public:
    UniqueHandle(size_t s) : data(new int[s]) {}

    // Destructor: Cleans up OWNED resources
    ~UniqueHandle() { delete[] data; }

    // Rule of 5: Move Constructor (T&&)
    UniqueHandle(UniqueHandle&& other) noexcept
        // 1. Shallow copy pointer
        : data(other.data)
    {
        // 2. Nullify source pointer
        other.data = nullptr;
    }

    // Prevents accidental copies when move is possible
    UniqueHandle(const UniqueHandle&) = delete;
    UniqueHandle& operator=(const UniqueHandle&) = delete;
};
